            <v-list density="compact">
              <v-list-item>
                <v-list-item-title>503 Errors (Service Unavailable):</v-list-item-title>
                <v-list-item-subtitle class="text-warning">
                  {{ error503Count }} ({{ error503Percent }}%)
                </v-list-item-subtitle>
              </v-list-item>
              <v-list-item>
                <v-list-item-title>400 Errors (Bad Request):</v-list-item-title>
                <v-list-item-subtitle class="text-error">
                  {{ error400Count }} ({{ error400Percent }}%)
                </v-list-item-subtitle>
              </v-list-item>
              <v-list-item>
                <v-list-item-title>Other Errors:</v-list-item-title>
