              :bin-count="10"
              title="Request Duration Distribution (ms)"
            />
          </v-card>
        </v-col>

        <!-- Request Timeline -->
        <v-col cols="12" v-if="showTimeline && stats && stats.length > 0 && stats.length <= 200">
          <v-card variant="outlined" class="pa-3">
            <h4>Request Timeline</h4>
            <div class="text-caption mb-2">Duration visualization (showing {{ stats.length }} requests)</div>
            <div class="timeline-container">
              <div 
                v-for="(stat, index) in stats" 
                :key="index"
                :class="['timeline-bar', getStatusClass(stat)]"
                :style="{ width: getBarWidth(stat) + '%', minHeight: '4px' }"
                :title="getTooltip(stat)"
              >
              </div>
