<script setup lang="ts">
import { computed } from 'vue';
import type { RequestStats } from '@/esri/services/TempoDataService';
import DurationHistogram from './DurationHistogram.vue';

interface Props {
  stats: RequestStats[] | null;
  showTimeline?: boolean;
}

const props = withDefaults(defineProps<Props>(), {
  showTimeline: true
});

defineEmits<{
  (e: 'clear'): void;
}>();

// Overall stats
const totalRequests = computed(() => props.stats?.length || 0);
const successfulRequests = computed(() => 
  props.stats?.filter(s => s.status === 'success').length || 0
);
const failedRequests = computed(() => totalRequests.value - successfulRequests.value);
const successRate = computed(() => 
  totalRequests.value > 0 
    ? Math.round((successfulRequests.value / totalRequests.value) * 100) 
    : 0
);
const failureRate = computed(() => 100 - successRate.value);
const retriedRequests = computed(() => 
  props.stats?.filter(s => s.retriedFrom503 === true).length || 0
);
const retriedPercent = computed(() => 
  totalRequests.value > 0 
    ? Math.round((retriedRequests.value / totalRequests.value) * 100) 
    : 0
);
const totalSamples = computed(() => 
  props.stats?.reduce((sum, s) => sum + s.sampleCount, 0) || 0
);

// Calculate unique locations from the stats
const uniqueLocations = computed(() => {
  if (!props.stats) return 0;
  // This is approximate since we don't have location data in stats
  // We can estimate based on sample count and requests
  return Math.round(totalSamples.value / Math.max(totalRequests.value, 1));
});

// Success rate color
const successRateColor = computed(() => {
  const rate = successRate.value;
  if (rate >= 95) return 'text-success';
  if (rate >= 85) return 'text-warning';
  return 'text-error';
});

// Error breakdown
const error503Count = computed(() => 
  props.stats?.filter(s => s.errorType === '503').length || 0
);
const error400Count = computed(() => 
  props.stats?.filter(s => s.errorType === '400').length || 0
);
const errorOtherCount = computed(() => 
  props.stats?.filter(s => s.errorType === 'other').length || 0
);

const error503Percent = computed(() => 
  totalRequests.value > 0 
    ? Math.round((error503Count.value / totalRequests.value) * 100) 
    : 0
);
const error400Percent = computed(() => 
  totalRequests.value > 0 
    ? Math.round((error400Count.value / totalRequests.value) * 100) 
    : 0
);
const errorOtherPercent = computed(() => 
  totalRequests.value > 0 
    ? Math.round((errorOtherCount.value / totalRequests.value) * 100) 
    : 0
);

// Get details of "other" errors with their messages
const otherErrorDetails = computed(() => {
  if (!props.stats) return [];
  
  const otherErrors = props.stats.filter(s => s.errorType === 'other');
  
  // Group by error message and count occurrences
  const errorMap = new Map<string, { type: string; message: string; count: number }>();
  
  otherErrors.forEach(stat => {
    const message = stat.errorMessage || 'Unknown error';
    const statusCode = stat.statusCode ? `HTTP ${stat.statusCode}` : 'Network Error';
    const key = `${statusCode}:${message}`;
    
    if (errorMap.has(key)) {
      errorMap.get(key)!.count++;
    } else {
      errorMap.set(key, {
        type: statusCode,
        message: message,
        count: 1
      });
    }
  });
  
  // Convert to array and sort by count (descending)
  return Array.from(errorMap.values()).sort((a, b) => b.count - a.count);
});

// Timing statistics
const minDuration = computed(() => {
  if (!props.stats || props.stats.length === 0) return 0;
  return Math.round(Math.min(...props.stats.map(s => s.duration)));
});

const maxDuration = computed(() => {
  if (!props.stats || props.stats.length === 0) return 0;
  return Math.round(Math.max(...props.stats.map(s => s.duration)));
});

const avgDuration = computed(() => {
  if (!props.stats || props.stats.length === 0) return 0;
  const sum = props.stats.reduce((acc, s) => acc + s.duration, 0);
  return Math.round(sum / props.stats.length);
});

const medianDuration = computed(() => {
  if (!props.stats || props.stats.length === 0) return 0;
  const sorted = [...props.stats].map(s => s.duration).sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return Math.round(
    sorted.length % 2 === 0 
      ? (sorted[mid - 1] + sorted[mid]) / 2 
      : sorted[mid]
  );
});

// Timeline helpers
function getStatusClass(stat: RequestStats): string {
  if (stat.status === 'success') return 'status-success';
  if (stat.errorType === '503') return 'status-503';
  if (stat.errorType === '400') return 'status-400';
  return 'status-error';
}

function getBarWidth(stat: RequestStats): number {
  if (maxDuration.value === 0) return 0;
  return (stat.duration / maxDuration.value) * 100;
}

function getTooltip(stat: RequestStats): string {
  const time = new Date(stat.timestamp).toLocaleTimeString();
  return `${time}: ${stat.status} - ${stat.duration.toFixed(0)}ms - ${stat.sampleCount} samples`;
}
</script>

